import React, { useState, useEffect, useRef } from 'react';
import SockJS from 'sockjs-client';
import Stomp from 'stompjs';
import './ChatComponent.css';

const ChatComponent = ({ currentUserId, receiverId }) => {
    const [messages, setMessages] = useState([]);
    const [newMessage, setNewMessage] = useState("");
    const stompClientRef = useRef(null);
    const messagesEndRef = useRef(null);

    // Auto-scroll to bottom when new message arrives
    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    useEffect(() => {
        // 1. Connect to Backend
        const socket = new SockJS('http://localhost:8080/ws');
        const client = Stomp.over(socket);

        // Disable debug logs to keep console clean
        client.debug = () => {};

        client.connect({}, () => {
            // 2. Subscribe to receive messages
            client.subscribe(`/topic/messages/${currentUserId}`, (message) => {
                const receivedMsg = JSON.parse(message.body);
                // Only add if it belongs to this specific conversation
                if (receivedMsg.senderId === receiverId) {
                    setMessages((prev) => [...prev, receivedMsg]);
                }
            });
        });

        stompClientRef.current = client;

        return () => {
            if (client && client.connected) client.disconnect();
        };
    }, [currentUserId, receiverId]);

    const sendMessage = (e) => {
        e.preventDefault();
        if (newMessage.trim() && stompClientRef.current) {
            const chatMessage = {
                senderId: currentUserId,
                receiverId: receiverId,
                content: newMessage,
                timestamp: Date.now(),
                isRead: false
            };

            // 3. Send to Backend
            stompClientRef.current.send("/app/chat", {}, JSON.stringify(chatMessage));

            // Add to UI immediately
            setMessages((prev) => [...prev, chatMessage]);
            setNewMessage("");
        }
    };

    return (
        <div className="chat-container">
            <div className="chat-box">
                {messages.length === 0 && (
                    <p style={{textAlign: 'center', color: '#888', fontSize: '0.8rem'}}>
                        Start chatting...
                    </p>
                )}

                {messages.map((msg, index) => (
                    <div
                        key={index}
                        className={`message-bubble ${msg.senderId === currentUserId ? 'sent' : 'received'}`}
                    >
                        {msg.content}
                    </div>
                ))}
                <div ref={messagesEndRef} />
            </div>

            <form className="chat-input-area" onSubmit={sendMessage}>
                <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    placeholder="Type..."
                />
                <button type="submit">➤</button>
            </form>
        </div>
    );
};

export default ChatComponent;
